package org.threeten.extra;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.time.Duration;

import org.junit.jupiter.api.Test;

public class TestSeconds_test_toDuration {

    private static final int FIRST_TESTED_SECOND = -20;
    private static final int AFTER_LAST_TESTED_SECOND = 20;

    @Test
    public void test_toDuration() {
        for (int i = FIRST_TESTED_SECOND; i < AFTER_LAST_TESTED_SECOND; i++) {
            assertEquals(Duration.ofSeconds(i), Seconds.of(i).toDuration());
        }
    }
}
